import { resolve } from "node:path";
import { defineConfig } from "vite";
import { routes, explore } from "./src/site/routes.js";

// Pages are generated by scripts/build-pages.mjs; the 3D model at explore/ is hand-written.
const input = Object.fromEntries([...routes, explore].map((r) => [r.id, resolve(__dirname, r.file)]));

export default defineConfig({
  server: { port: 5173, strictPort: false },
  preview: { port: 4173, strictPort: true },
  // three.js is ~600 kB and loads only on /explore, behind a dynamic import.
  build: { target: "es2022", chunkSizeWarningLimit: 700, rollupOptions: { input } },
});
